// Web Push (PWA notifications). VAPID keys are generated by the Worker on first
// use and kept in app_settings, so nothing has to be configured by hand.
import { buildPushPayload, type PushSubscription } from '@block65/webcrypto-web-push';
import { getRates } from '../fx/service';
import { fmtWhen } from '../../lib/tz';
import { STATUS_LABEL, type JobStatus } from '../../types';

interface Vapid { publicKey: string; privateKey: string }

const b64u = (buf: ArrayBuffer) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

async function setting(db: D1Database, key: string): Promise<string | null> {
  const r = await db.prepare('SELECT value FROM app_settings WHERE key = ?').bind(key).first<{ value: string }>();
  return r?.value ?? null;
}
export async function putSetting(db: D1Database, key: string, value: string) {
  await db.prepare("INSERT INTO app_settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')").bind(key, value).run();
}

export async function getVapid(db: D1Database): Promise<Vapid> {
  const raw = await setting(db, 'vapid_keys');
  if (raw) return JSON.parse(raw) as Vapid;
  const kp = (await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify'])) as CryptoKeyPair;
  const pub = (await crypto.subtle.exportKey('raw', kp.publicKey)) as ArrayBuffer;
  const jwk = (await crypto.subtle.exportKey('jwk', kp.privateKey)) as JsonWebKey;
  const v: Vapid = { publicKey: b64u(pub), privateKey: jwk.d! };
  await db.prepare("INSERT INTO app_settings (key, value) VALUES ('vapid_keys', ?) ON CONFLICT(key) DO NOTHING").bind(JSON.stringify(v)).run();
  return JSON.parse((await setting(db, 'vapid_keys'))!) as Vapid;
}

export interface Note { title: string; body: string; url?: string; tag?: string }

export async function sendPush(db: D1Database, note: Note): Promise<{ sent: number; failed: number }> {
  const { results } = await db.prepare('SELECT * FROM push_subscriptions').all<{ id: number; endpoint: string; p256dh: string; auth: string }>();
  const subs = results ?? [];
  if (!subs.length) return { sent: 0, failed: 0 };
  const v = await getVapid(db);
  // VAPID contact: the app's own address (saved when a device subscribes).
  const subject = (await setting(db, 'app_origin')) ?? 'https://jobseeker.workers.dev';
  let sent = 0, failed = 0;
  for (const s of subs) {
    const sub: PushSubscription = { endpoint: s.endpoint, expirationTime: null, keys: { p256dh: s.p256dh, auth: s.auth } };
    try {
      const payload = await buildPushPayload(
        { data: JSON.stringify(note), options: { ttl: 6 * 3600, urgency: 'high', topic: note.tag?.replace(/[^\w-]/g, '').slice(0, 32) } },
        sub,
        { subject, publicKey: v.publicKey, privateKey: v.privateKey },
      );
      const res = await fetch(s.endpoint, payload as RequestInit);
      if (res.status === 404 || res.status === 410) await db.prepare('DELETE FROM push_subscriptions WHERE id = ?').bind(s.id).run();
      if (res.ok) sent++;
      else {
        failed++;
        console.error('push rejected', res.status, await res.text().catch(() => ''));
      }
    } catch (e) {
      console.error('push failed', e);
      failed++;
    }
  }
  return { sent, failed };
}

// ------------------------------------------------------------------ what to notify about (cron, every 15 min)

const belgradeDay = (d = new Date()) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Belgrade' }).format(d);
const belgradeHour = (d = new Date()) => Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Belgrade', hour: '2-digit', hour12: false }).format(d));

export async function runNotifications(db: D1Database): Promise<void> {
  await getRates(db).catch(() => null); // keeps the NBS rate fresh too

  const hasSubs = await db.prepare('SELECT 1 AS x FROM push_subscriptions LIMIT 1').first();

  // 1) Status changes and new jobs since the last snapshot.
  const { results } = await db.prepare('SELECT id, company, title, status FROM jobs').all<{ id: number; company: string; title: string; status: JobStatus }>();
  const jobs = results ?? [];
  const snapRaw = await setting(db, 'push_snapshot');
  const snap: Record<string, string> = snapRaw ? JSON.parse(snapRaw) : {};
  const notes: Note[] = [];
  if (snapRaw && hasSubs) {
    const fresh = jobs.filter((j) => !(String(j.id) in snap));
    for (const j of jobs) {
      const before = snap[String(j.id)];
      if (!before || before === j.status) continue;
      if (!['interview', 'offer', 'rejected', 'applied'].includes(j.status)) continue;
      // Only changes Alex did not make himself (the agent writes actor 'agent').
      const ev = await db.prepare('SELECT actor FROM job_events WHERE job_id = ? ORDER BY id DESC LIMIT 1').bind(j.id).first<{ actor: string }>();
      if (ev && ev.actor !== 'agent') continue;
      const icon = j.status === 'interview' ? '📅' : j.status === 'offer' ? '🎉' : j.status === 'rejected' ? '✖' : '✓';
      notes.push({ title: `${icon} ${STATUS_LABEL[j.status]}: ${j.company}`, body: j.title, url: `/jobs/${j.id}`, tag: `job-${j.id}` });
    }
    if (fresh.length > 0) {
      notes.push({
        title: `Agent: ${fresh.length} ${fresh.length === 1 ? 'nov oglas' : 'novih oglasa'}`,
        body: fresh.slice(0, 3).map((j) => `${j.company} · ${j.title}`).join('\n'),
        url: '/jobs?status=review&status=ready',
        tag: 'new-jobs',
      });
    }
  }
  await putSetting(db, 'push_snapshot', JSON.stringify(Object.fromEntries(jobs.map((j) => [String(j.id), j.status]))));

  if (!hasSubs) return;

  // 2) Interview reminders ~1 h before.
  const now = Date.now();
  const { results: ivs } = await db
    .prepare(
      `SELECT i.id, i.title, i.starts_at, i.location, i.job_id, j.company FROM interviews i LEFT JOIN jobs j ON j.id = i.job_id
       WHERE i.reminded_at IS NULL AND i.starts_at > ? AND i.starts_at <= ?`,
    )
    .bind(new Date(now).toISOString(), new Date(now + 75 * 60000).toISOString())
    .all<{ id: number; title: string | null; starts_at: string; location: string | null; job_id: number | null; company: string | null }>();
  for (const iv of ivs ?? []) {
    notes.push({
      title: `⏰ Intervju uskoro${iv.company ? `: ${iv.company}` : ''}`,
      body: `${fmtWhen(iv.starts_at)} · ${iv.title ?? 'Intervju'}${iv.location ? `\n${iv.location}` : ''}`,
      url: iv.job_id ? `/jobs/${iv.job_id}?tab=intervjui` : '/calendar',
      tag: `iv-${iv.id}`,
    });
    await db.prepare("UPDATE interviews SET reminded_at = datetime('now') WHERE id = ?").bind(iv.id).run();
  }

  // 2b) "Kako je prošlo?" ~30 min after an interview ends, if not rated yet.
  const { results: done } = await db
    .prepare(
      `SELECT i.id, i.job_id, i.starts_at, i.duration_min, j.company FROM interviews i LEFT JOIN jobs j ON j.id = i.job_id
       LEFT JOIN interview_feedback f ON f.interview_id = i.id
       WHERE f.interview_id IS NULL AND i.feedback_asked_at IS NULL AND i.starts_at > ? AND i.starts_at < ?`,
    )
    .bind(new Date(now - 3 * 86400e3).toISOString(), new Date(now).toISOString())
    .all<{ id: number; job_id: number | null; starts_at: string; duration_min: number; company: string | null }>();
  for (const iv of done ?? []) {
    const end = new Date(iv.starts_at).getTime() + (iv.duration_min || 45) * 60000;
    if (now < end + 30 * 60000) continue;
    notes.push({
      title: `Kako je prošlo${iv.company ? ` sa ${iv.company}` : ''}?`,
      body: 'Zapiši kako si se osećao i oceni intervjuera dok ti je sveže. Traje minut.',
      url: iv.job_id ? `/jobs/${iv.job_id}?tab=intervjui#fb-${iv.id}` : `/calendar#fb-${iv.id}`,
      tag: `fb-${iv.id}`,
    });
    await db.prepare("UPDATE interviews SET feedback_asked_at = datetime('now') WHERE id = ?").bind(iv.id).run();
  }

  // 3) Morning digest (once a day, after 8:00 Belgrade): today's interviews + due follow-ups.
  const today = belgradeDay();
  if (belgradeHour() >= 8 && (await setting(db, 'push_digest_day')) !== today) {
    await putSetting(db, 'push_digest_day', today);
    const fu = await db.prepare("SELECT company FROM jobs WHERE status = 'applied' AND follow_up_on IS NOT NULL AND follow_up_on <= ?").bind(today).all<{ company: string }>();
    const { results: allIv } = await db
      .prepare('SELECT starts_at FROM interviews WHERE starts_at BETWEEN ? AND ?')
      .bind(new Date(now - 24 * 3600e3).toISOString(), new Date(now + 24 * 3600e3).toISOString())
      .all<{ starts_at: string }>();
    const nToday = (allIv ?? []).filter((x) => belgradeDay(new Date(x.starts_at)) === today).length;
    const parts: string[] = [];
    if (nToday) parts.push(`${nToday} ${nToday === 1 ? 'intervju' : 'intervjua'} danas`);
    const fuList = fu.results ?? [];
    if (fuList.length) parts.push(`Follow-up: ${fuList.slice(0, 4).map((x) => x.company).join(', ')}${fuList.length > 4 ? '…' : ''}`);
    if (parts.length) notes.push({ title: 'Jobseeker danas', body: parts.join('\n'), url: '/', tag: 'digest' });
  }

  for (const n of notes.slice(0, 8)) await sendPush(db, n);
}
